frappe.raven_notification = {
    setup_value_change_fields: function (frm) {
        if (!frm.doc.document_type) return;
        
        frappe.model.with_doctype(frm.doc.document_type, function () {
            let fields = frappe.get_doc("DocType", frm.doc.document_type).fields;
            
            // Helper: format fieldname + label
            let get_option = function (df) {
                return {
                    value: df.fieldname,
                    label: `${df.fieldname} (${__(df.label, null, df.parent)})`,
                };
            };
            
            // Only include "value" fields, skip layout/system
            let options = $.map(fields, function (df) {
                return frappe.model.no_value_type.includes(df.fieldtype) ? null : get_option(df);
            });
            
            // Add some system fields explicitly
            options.push({ value: "owner", label: "owner (Owner)" });
            options.push({ value: "modified", label: "modified (Last Modified)" });
            
            // Set into field
            frm.set_df_property(
                "custom_field_to_watch",
                "options",
                [""].concat(options.map((o) => o.label))
            );
            
            // Store map of label → value for later (so you know fieldname in backend)
            frm.value_field_map = {};
            options.forEach((o) => (frm.value_field_map[o.label] = o.value));
            
            console.log("test Shanab ", frm.value_field_map);
        });
    },
};

frappe.ui.form.on("Raven Document Notification", {
    document_type: function (frm) {
        frappe.raven_notification.setup_value_change_fields(frm);
    },
    refresh: function (frm) {
        frappe.raven_notification.setup_value_change_fields(frm);
    },
});
